INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Eesti Kunstimuuseum KUMU', 24.79000000, 59.43000000, 'Baltimaade suurim kunstimuuseum, kus leidub Eesti kunsti klassikast kaasaegse kunstini. Nimekonkursil 2004.a võitis sõnade "kunst" ja "muuseum" esitähtede kombo.', 'A', 'data:image/jpeg;base64,');
INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Tallinna Linnamuuseum', 24.75000000, 59.43000000, 'Tutvustab pealinna ajalugu ja keskaegset elu vanalinnas. Muuseum koosneb seitsmest selgelt eristuva looga filiaalist, mis teevad omavahel tihedat koostööd', 'A', 'data:image/jpeg;base64,');
