INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Kõpu tuletorn', 22.22000000, 58.91000000, 'Üks maailma vanimaid töötavaid tuletorne, 16.sajand ehitatud. Asub ühe saare kõrgeimas punktis.1989–1990 valati tornile ümber tugev raudbetoonist "särk", mis peab hoidma ära torni kokkuvarisemise.', 'A', 'data:image/jpeg;base64,');
