INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Pakri tuletorn', 24.03000000, 59.38000000, 'Eesti kõrgeim tuletorn, asub pankrannikul Paldiski lähedal. Samanimelised on ja Suur- ja Väike- ...', 'A', 'data:image/jpeg;base64,');
INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Keri tuletorn', 25.02000000, 59.69000000, 'Pisikesel saarel asuv tuletorn, mida ümbritseb unikaalne looduskeskkond. 2002. aastal lahkus saarelt viimane majakavaht. Poolel teel soome.', 'A', 'data:image/jpeg;base64,');
INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Ruhnu tuletorn', 23.25000000, 57.80000000, 'Prantsusmaal valmistatud metallist tuletorn, mis pärineb 19. sajandist. Saarel, kus asub see tuletorn nähti ka karu, kes Lätti ujus.', 'A', 'data:image/jpeg;base64,');
