INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Tallinna Toompea loss', 24.73000000, 59.43000000, 'Eesti ajalooline ja poliitiline keskus, kus asub ka Riigikogu.', 'A', 'data:image/jpeg;base64,');
