INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Narva linnus', 28.20000000, 59.37000000, 'See ajalooline piiskopilinnus asub Eesti ja Venemaa piiril.', 'A', 'data:image/jpeg;base64,');
