INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Rakvere linnus', 26.35000000, 59.34000000, 'Ühe linna südames asuv iidne loss, kus saab tutvuda keskaegsete relvadega. Seal on lossivaremed ja kostümeeritud näitlejad, kes taaselustavad keskaegset elu-olu, töid ja sõda.', 'A', 'data:image/jpeg;base64,');
INSERT INTO game.location (name, longitude, latitude, clue, status, image_data) VALUES ('Puurmani mõis', 26.28000000, 58.57000000, 'Muistne loss, kus peetakse mitmesuguseid kultuuriüritusi ja tegutseb Mõisakool alates 1923a. Puurmani mõisa esimene omanik oli Buhrmeisterite suguvõsa. Pedja jõgi voolab läbi selle valla.', 'A', 'data:image/jpeg;base64,');
